example_item.example_item_data:
% In a terminal, start Ollama and pull a model first: % ollama serve % ollama pull llama3.2
opts = aioptions('Provider', 'ollama', ... 'Model', 'llama3.2', ... 'Endpoint', 'http://127.0.0.1:11434/api/generate', ... 'Timeout', 120, ... 'SystemPrompt', 'Return only Nelson code. Nelson functions use syntax: function y = name(x), statements, end.', ... 'Think', false, ... 'NumPredict', 200, ... 'Temperature', 0);
answer = aiask('Write function y = vector_mean(x). Use y = mean(x).', opts)

opts = aioptions('Provider', 'ollama', 'Model', 'llama3.2');
[text, response] = aiask('Explain the difference between plot and semilogy in Nelson.', opts);
disp(text)
disp(response.total_duration)
